      color: var(--ink);
      text-align: start;
      cursor: pointer;
      transition: border-color 0.2s ease, background-color 0.2s ease, transform 0.2s var(--ease);
    }

    .quiz-option:hover:not(:disabled) {
      transform: translateX(-2px);
      border-color: var(--line-strong);
      background: var(--paper-bright);
    }

    .quiz-option[aria-pressed="true"] {
      border-color: var(--green);
      background: var(--green-soft);
    }

    .quiz-option[aria-pressed="true"] .option-letter {
      border-color: var(--green);
      background: var(--green);
      color: var(--paper-bright);
    }

    .quiz-option.is-correct {
      border-color: var(--green);
      background: var(--green-soft);
    }

    .quiz-option.is-correct .option-letter {
      border-color: var(--green);
      background: var(--green);
      color: var(--paper-bright);
    }

    .quiz-option.is-wrong {
      border-color: var(--terracotta-line);
      background: var(--terracotta-soft);
    }

    .quiz-option.is-wrong .option-letter {
      border-color: var(--terracotta);
      background: var(--terracotta);
      color: var(--paper-bright);
    }

    .quiz-option:disabled {
      cursor: default;
    }

    .quiz-option:disabled:hover {
      transform: none;
    }

    .option-letter {
      width: 30px;
      height: 30px;
      flex: 0 0 30px;
      display: grid;
      place-items: center;
      border: 1px solid var(--line);
      border-radius: 50%;
      color: var(--muted);
      background: rgba(251, 248, 240, 0.7);
      font-size: 11px;
      line-height: 1;
      transition: background-color 0.2s ease, color 0.2s ease, border-color 0.2s ease;
    }

    .option-text {
      flex: 1;
      font-size: 13px;
      line-height: 1.7;
    }

    .option-mark {
      width: 18px;
      height: 18px;
      flex: 0 0 18px;
      color: var(--green);
      opacity: 0;
      transition: opacity 0.2s ease;
    }

    .option-mark .icon {
      width: 17px;
      height: 17px;
      stroke-width: 2;
    }

    .quiz-option.is-correct .option-mark,
    .quiz-option.is-wrong .option-mark {
      opacity: 1;
    }

    .quiz-option.is-wrong .option-mark {
      color: var(--terracotta);
    }

    .quiz-footer {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      margin-top: 18px;
    }

    .quiz-footer .activity-hint {
      max-width: 330px;
    }

    .rail {
      display: grid;
      gap: 14px;
      position: sticky;
      top: 18px;
    }

    .rail-card {
      padding: 21px;
      border: 1px solid rgba(207, 197, 178, 0.86);
      border-radius: var(--radius-md);
      background: rgba(251, 248, 240, 0.6);
    }

    .rail-title {
      margin: 0 0 16px;
      color: var(--ink);
      font-size: 13px;
      line-height: 1.6;
    }

    .path-list {
      display: grid;
      gap: 0;
      margin: 0;
      padding: 0;
      list-style: none;
    }

    .path-step {
      position: relative;
      display: flex;
      gap: 11px;
      align-items: flex-start;
      min-height: 57px;
      padding-bottom: 17px;
    }

    .path-step:last-child {
      min-height: 0;
      padding-bottom: 0;
    }

    .path-step:not(:last-child)::before {
      content: "";
      position: absolute;
      top: 27px;
      bottom: 0;
      inset-inline-start: 12px;
      width: 1px;
      background: var(--line);
    }

    .path-step.is-done:not(:last-child)::before {
      background: var(--green-line);
    }

    .path-marker {
      position: relative;
      z-index: 1;
      width: 25px;
      height: 25px;
      flex: 0 0 25px;
      display: grid;
      place-items: center;
      border: 1px solid var(--line);
      border-radius: 50%;
      background: var(--paper);
      color: var(--muted);
      font-size: 9px;
      line-height: 1;
    }

    .path-step.is-done .path-marker {
      border-color: var(--green);
      background: var(--green);
      color: var(--gold-soft);
    }

    .path-step.is-current .path-marker {
      border-color: var(--gold);
      color: var(--gold);
      box-shadow: 0 0 0 4px rgba(179, 149, 92, 0.1);
    }

    .path-text {
      display: flex;
      flex-direction: column;
      gap: 1px;
      min-width: 0;
      padding-top: 1px;
    }

    .path-text strong {
      font-size: 12px;
      line-height: 1.6;
      font-weight: 700;
    }

    .path-text span {
      color: var(--muted);
      font-size: 10px;
      line-height: 1.6;
    }

    .path-step.is-done .path-text span {
      color: var(--green);
    }

    .rail-note {
      display: flex;
      gap: 10px;
      align-items: flex-start;
      padding: 15px 16px;
      border: 1px dashed var(--line-strong);
      border-radius: 14px;
      color: var(--muted);
      background: rgba(251, 248, 240, 0.32);
      font-size: 10.5px;
      line-height: 1.75;
    }

    .rail-note .icon {
      width: 16px;
      height: 16px;
      flex: 0 0 16px;
      margin-top: 2px;
      color: var(--gold);
    }

    .completion-card {
      display: flex;
      align-items: center;
      gap: 17px;
      margin-top: 20px;
      padding: 21px 23px;
      border: 1px solid var(--green-line);
      border-radius: var(--radius-md);
      background:
        radial-gradient(circle at 95% 0%, rgba(179, 149, 92, 0.16), transparent 38%),
        linear-gradient(135deg, rgba(228, 237, 230, 0.78), rgba(251, 248, 240, 0.88));
      box-shadow: var(--shadow-sm);
      animation: soft-in 0.5s var(--ease) both;
    }

    .completion-seal {
      width: 52px;
      height: 52px;
      flex: 0 0 52px;
      display: grid;
      place-items: center;
      border: 1px solid var(--green);
      border-radius: 50%;
      background: var(--green);
      color: var(--gold-soft);
      box-shadow: 0 0 0 7px rgba(31, 75, 66, 0.07);
    }

    .completion-seal .icon {
      width: 24px;
      height: 24px;
      stroke-width: 1.6;
    }

    .completion-copy {
      flex: 1;
      min-width: 0;
    }

    .completion-copy .eyebrow {
      margin-bottom: 5px;
      font-size: 10px;
    }

    .completion-copy .eyebrow::before {
      width: 18px;
      flex-basis: 18px;
    }

    .completion-copy h2 {
      margin: 0;
      font-size: 18px;
      line-height: 1.5;
    }

    .completion-copy p {
      margin: 5px 0 0;
      color: var(--muted);
      font-size: 11px;
      line-height: 1.75;
    }

    .completion-card .btn {
      min-height: 40px;
      flex: 0 0 auto;
    }

    .source-card {
      display: grid;
      grid-template-columns: auto minmax(0, 1fr);
      gap: 18px;
      margin-top: 22px;
      padding: 24px;
      border: 1px solid var(--line);
      border-radius: var(--radius-md);
      background: rgba(251, 248, 240, 0.62);
    }

    .source-icon {
      width: 43px;
      height: 43px;
      display: grid;
      place-items: center;
      border: 1px solid var(--line);
      border-radius: 13px;
      background: rgba(255, 253, 248, 0.65);
      color: var(--green);
    }

    .source-icon .icon {
      width: 21px;
      height: 21px;
    }

    .source-head {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 14px;
      flex-wrap: wrap;
    }

    .source-head h2 {
      margin: 0;
      font-size: 17px;
      line-height: 1.5;
    }

    .source-status {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      padding: 3px 9px;
      border: 1px solid var(--gold-soft);
      border-radius: 999px;
      color: var(--terracotta);
      background: var(--gold-pale);
      font-size: 10px;
      line-height: 1.5;
    }

    .source-field {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 14px;
      margin-top: 13px;
      padding: 11px 13px;
      border: 1px dashed var(--line-strong);
      border-radius: 10px;
      background: rgba(255, 253, 248, 0.46);
    }

    .source-field span {
      color: var(--muted);
      font-size: 10.5px;
    }

    .source-field strong {
      color: var(--ink-soft);
      font-size: 12px;
      line-height: 1.6;
      font-weight: 700;
    }

    .source-copy p {
      margin: 8px 0 0;
      color: var(--muted);
      font-size: 11px;
      line-height: 1.8;
    }

    .lesson-end {
      display: flex;
      justify-content: center;
      padding: 27px 0 42px;
    }

    .lesson-end .btn {
      min-height: 42px;
      color: var(--muted);
      font-size: 12px;
      border-color: var(--line);
      background: rgba(251, 248, 240, 0.3);
    }

    .toast {
      position: fixed;
      inset-inline: 16px;
      bottom: 18px;
      z-index: 30;
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 10px;
      max-width: 420px;
      margin-inline: auto;
      padding: 12px 16px;
      border: 1px solid var(--green-line);
      border-radius: 13px;
      background: rgba(23, 60, 53, 0.96);
      color: var(--paper-bright);
      box-shadow: 0 18px 45px rgba(23, 60, 53, 0.22);
      font-size: 12px;
      line-height: 1.6;
      text-align: center;
      animation: toast-in 0.35s var(--ease) both;
      pointer-events: none;
    }

    .toast .icon {
      width: 16px;
      height: 16px;
      flex: 0 0 16px;
      color: var(--gold-soft);
    }

    @keyframes rise-in {
      from {
        opacity: 0;
        transform: translateY(16px);
      }
      to {
        opacity: 1;
        transform: translateY(0);
      }
    }

    @keyframes fade-in {
      from { opacity: 0; }
      to { opacity: 1; }
    }

    @keyframes soft-in {
      from {
        opacity: 0;
        transform: translateY(6px);
      }
      to {
        opacity: 1;
        transform: translateY(0);
      }
    }

    @keyframes toast-in {
      from {
        opacity: 0;
        transform: translateY(10px);
      }
      to {
        opacity: 1;
        transform: translateY(0);
      }
    }

    @media (max-width: 960px) {
      .shell {
        width: min(calc(100% - 36px), var(--shell));
      }

      .hero {
        grid-template-columns: minmax(0, 1fr) minmax(280px, 0.72fr);
        gap: 30px;
        min-height: auto;
      }

      .hero h1 {
        font-size: clamp(43px, 7vw, 66px);
      }

      .hero-facts {
        grid-template-columns: 1fr;
        gap: 9px;
      }

      .fact p {
        max-width: 320px;
      }

      .lesson-head {
        grid-template-columns: 1fr;
        gap: 20px;
        align-items: stretch;
      }

      .progress-card {
        max-width: none;
      }

      .lesson-layout {
        grid-template-columns: 1fr;
      }

      .rail {
        position: static;
        grid-row: 2;
      }

      .rail-card {
        display: none;
      }

      .rail-note {
        max-width: none;
      }
    }

    @media (max-width: 720px) {
      body {
        font-size: 16px;
      }

      .site-header {
        min-height: 76px;
        padding-block: 14px;
      }

      .brand-mark {
        width: 42px;
        height: 42px;
        flex-basis: 42px;
        border-radius: 13px;
      }

      .brand-mark .icon {
        width: 24px;
        height: 24px;
      }

      .brand-text strong {
        font-size: 18px;
      }

      .brand-text span {
        display: none;
      }

      .header-status {
        display: none;
      }

      .hero {
        grid-template-columns: 1fr;
        gap: 35px;
        padding-block: 18px 30px;
      }

      .hero h1 {
        font-size: clamp(40px, 11vw, 58px);
      }

      .hero-lede {
        margin-top: 18px;
        font-size: 17px;
      }

      .hero-actions {
        align-items: stretch;
        flex-direction: column;
        gap: 11px;
        margin-top: 26px;
      }

      .hero-actions .btn-primary {
        width: 100%;
      }

      .hero-meta {
        max-width: none;
        text-align: center;
        font-size: 11.5px;
      }

      .hero-facts {
        grid-template-columns: 1fr;
        gap: 11px;
        margin-top: 28px;
        padding-top: 20px;
      }

      .hero-art {
        max-width: 340px;
      }

      .art-note {
        inset-inline-start: -4px;
        bottom: 28px;
        padding: 9px 11px;
        font-size: 10px;
      }

      .principles {
        grid-template-columns: 1fr;
        margin-bottom: 35px;
        gap: 1px;
      }

      .principle {
        padding: 18px 17px;
      }

      .site-footer {
        flex-direction: column;
        align-items: flex-start;
        gap: 8px;
        padding-block: 20px 26px;
      }

      .site-footer span:last-child {
        max-width: 95%;
      }

      .lesson-head {
        padding-bottom: 25px;
      }

      .lesson-heading h1 {
        font-size: 36px;
      }

      .lesson-intro {
        font-size: 14.5px;
      }

      .lesson-chips {
        margin-top: 15px;
      }

      .progress-card {
        padding: 18px;
      }

      .panel {
        padding: 18px 15px 20px;
        border-radius: 22px;
      }

      .panel-head {
        grid-template-columns: auto minmax(0, 1fr);
        gap: 10px;
      }

      .panel-head .activity-state {
        grid-column: 1 / -1;
        justify-self: start;
        margin-top: 2px;
      }

      .panel-title-wrap h2 {
        font-size: 23px;
      }

      .panel-title-wrap p {
        font-size: 11.5px;
      }

      .step-badge {
        min-width: 31px;
        height: 31px;
        padding: 3px 7px;
        font-size: 10px;
      }

      .order-grid {
        gap: 7px;
        margin-top: 20px;
      }

      .order-card {
        min-height: 190px;
        padding: 35px 6px 14px;
        gap: 7px;
        border-radius: 16px;
      }

      .slot-number {
        top: 8px;
        inset-inline-start: 8px;
        width: 21px;
        height: 21px;
        font-size: 9px;
      }

      .card-icon {
        width: 47px;
        height: 47px;
      }

      .card-icon .icon {
        width: 22px;
        height: 22px;
      }

      .card-title {
        font-size: 16px;
      }

      .card-note {
        font-size: 9px;
        line-height: 1.55;
      }

      .card-action {
        font-size: 8.5px;
      }

      .activity-footer,
      .quiz-footer {
        align-items: stretch;
        flex-direction: column;
        gap: 12px;
      }

      .activity-hint {
        font-size: 10px;
      }

      .panel-actions {
        justify-content: stretch;
      }

      .panel-actions .btn {
        flex: 1;
      }

      .quiz-option {
        min-height: 56px;
        padding: 10px 11px;
        gap: 10px;
      }

      .option-text {
        font-size: 12.5px;
      }

      .completion-card {
        align-items: flex-start;
        flex-wrap: wrap;
        padding: 18px;
      }

      .completion-copy {
        flex-basis: calc(100% - 70px);
      }

      .completion-card .btn {
        width: 100%;
      }

      .source-card {
        padding: 18px 16px;
        gap: 12px;
      }

      .source-field {
        align-items: flex-start;
        flex-direction: column;
        gap: 3px;
      }

      .lesson-end {
        padding-bottom: 30px;
      }
    }

    @media (max-width: 380px) {
      .shell {
        width: min(calc(100% - 28px), var(--shell));
      }

      .hero h1 {
        font-size: 39px;
      }

      .order-card {
        min-height: 180px;
        padding: 32px 4px 12px;
      }

      .card-icon {
        width: 42px;
        height: 42px;
      }

      .card-title {
        font-size: 14.5px;
      }

      .card-note {
        font-size: 8.5px;
      }

      .option-letter {
        width: 27px;
        height: 27px;
        flex-basis: 27px;
        font-size: 10px;
      }

      .option-text {
        font-size: 12px;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      html {
        scroll-behavior: auto;
      }

      *,
      *::before,
      *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
      }
    }
  </style>
</head>
<body>

